document.addEventListener('click',function(event){var tab=event.target.closest('[data-bs-toggle="tab"]');if(tab){event.preventDefault();var target=document.querySelector(tab.getAttribute('data-bs-target'));if(!target)return;var list=tab.closest('.nav-tabs');var content=target.closest('.tab-content');if(!list||!content)return;list.querySelectorAll('.nav-link').forEach(function(item){item.classList.remove('active');item.setAttribute('aria-selected','false')});content.querySelectorAll('.tab-pane').forEach(function(panel){panel.classList.remove('active','show')});tab.classList.add('active');tab.setAttribute('aria-selected','true');target.classList.add('active','show');return}var toggler=event.target.closest('[data-bs-toggle="collapse"]');if(toggler){var panel=document.querySelector(toggler.getAttribute('data-bs-target'));if(panel){panel.classList.toggle('show');toggler.setAttribute('aria-expanded',panel.classList.contains('show'))}return}var close=event.target.closest('[data-bs-dismiss="alert"]');if(close){var alert=close.closest('.alert');if(alert)alert.remove()}});
